#include <stdio.h>
#include <stdlib.h>

// Функция для чтения матрицы из файла
int** read_matrix(const char* filename, int* rows, int* cols) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Ошибка открытия файла: %s\n", filename);
        exit(1);
    }

    // Чтение размеров
    fscanf(file, "%d %d", rows, cols);

    // Выделение памяти для матрицы
    int** matrix = (int**)malloc((*rows) * sizeof(int*));
    for (int i = 0; i < *rows; i++) {
        matrix[i] = (int*)malloc((*cols) * sizeof(int));
    }

    // Чтение элементов
    for (int i = 0; i < *rows; i++) {
        for (int j = 0; j < *cols; j++) {
            fscanf(file, "%d", &matrix[i][j]);
        }
    }

    fclose(file);
    return matrix;
}

// Функция для вывода матрицы
void print_matrix(int** matrix, int rows, int cols) {
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            printf("%d ", matrix[i][j]);
        }
        printf("\n");
    }
}

// Функция для сложения двух матриц
int** add_matrices(int** a, int** b, int rows, int cols) {
    int** result = (int**)malloc(rows * sizeof(int*));
    for (int i = 0; i < rows; i++) {
        result[i] = (int*)malloc(cols * sizeof(int));
    }

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            result[i][j] = a[i][j] + b[i][j];
        }
    }

    return result;
}

// Функция для вычитания двух матриц
int** subtract_matrices(int** a, int** b, int rows, int cols) {
    int** result = (int**)malloc(rows * sizeof(int*));
    for (int i = 0; i < rows; i++) {
        result[i] = (int*)malloc(cols * sizeof(int));
    }

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            result[i][j] = a[i][j] - b[i][j];
        }
    }

    return result;
}

// Функция для умножения двух матриц
int** multiply_matrices(int** a, int** b, int rows, int cols) {
    int** result = (int**)malloc(rows * sizeof(int*));
    for (int i = 0; i < rows; i++) {
        result[i] = (int*)malloc(cols * sizeof(int));
    }

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            result[i][j] = 0;
            for (int k = 0; k < cols; k++) {
                result[i][j] += a[i][k] * b[k][j];
            }
        }
    }

    return result;
}

// Функция для освобождения памяти
void free_matrix(int** matrix, int rows) {
    for (int i = 0; i < rows; i++) {
        free(matrix[i]);
    }
    free(matrix);
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Использование: %s <имя_файла_A> <имя_файла_B>\n", argv[0]);
        return 1;
    }

    char* file_a = argv[1];
    char* file_b = argv[2];

    // Чтение матриц
    int rows, cols;
    int** matrix_a = read_matrix(file_a, &rows, &cols);
    int** matrix_b = read_matrix(file_b, &rows, &cols);

    // Вычисление результатов
    int** sum = add_matrices(matrix_a, matrix_b, rows, cols);
    int** diff = subtract_matrices(matrix_a, matrix_b, rows, cols);
    int** product = multiply_matrices(matrix_a, matrix_b, rows, cols);

    // Вывод результатов
    print_matrix(sum, rows, cols);
    printf("\n");
    print_matrix(diff, rows, cols);
    printf("\n");
    print_matrix(product, rows, cols);

    // Освобождение памяти
    free_matrix(matrix_a, rows);
    free_matrix(matrix_b, rows);
    free_matrix(sum, rows);
    free_matrix(diff, rows);
    free_matrix(product, rows);

    return 0;
}

