    printf("Введите N и k: ");
    scanf("%d %d", &N, &k);

    // Вычисляем сумму 1^k + 2^k + 3^k + ... + N^k
    for (int i = 1; i <= N; i++) {
        long long power = 1;
        // Вычисляем i^k с помощью цикла
