#include <stdio.h>

int main() {
    int a, b, x, y, z;

    // Считываем размеры отверстия и габариты кирпича
    scanf("%d %d", &a, &b);
    scanf("%d %d %d", &x, &y, &z);

    // Находим три возможных пары сторон кирпича (все перестановки)
    // Кирпич проходит, если две его меньшие стороны не превышают соответствующие стороны отверстия

    // Сортируем стороны кирпича по возрастанию
    int sides[3];
    sides[0] = x;
    sides[1] = y;
    sides[2] = z;

    // Сортировка
    if (sides[0] > sides[1]) {
        int temp = sides[0];
        sides[0] = sides[1];
        sides[1] = temp;
    }
    if (sides[1] > sides[2]) {
        int temp = sides[1];
        sides[1] = sides[2];
        sides[2] = temp;
    }
    if (sides[0] > sides[1]) {
        int temp = sides[0];
        sides[0] = sides[1];
        sides[1] = temp;
    }

    // Теперь sides[0] <= sides[1] <= sides[2]
    // Кирпич проходит, если две меньшие стороны (sides[0] и sides[1]) укладываются в отверстие
    // То есть: sides[0] <= a и sides[1] <= b, или sides[0] <= b и sides[1] <= a

    if ((sides[0] <= a && sides[1] <= b) || (sides[0] <= b && sides[1] <= a)) {
        printf("yes\n");
    } else {
        printf("no\n");
    }

    return 0;
}

