            result[i] = hexDigits[temp % 16];
            temp /= 16;
            i++;
        }

        // Вывод в обратном порядке (с конца)
        for (int j = i - 1; j >= 0; j--) {
            printf("%c", result[j]);
        }
    }

    printf("\n");
    return 0;
}

#include <stdio.h>
#include <math.h>

int main() {
    double a, b, h;
    double x;

    printf("Введите три числа a, b, h: ");
    scanf("%lf %lf %lf", &a, &b, &h);

    // Проверка на корректность шага и диапазона
    if (h <= 0) {
        printf("Ошибка: шаг h должен быть положительным.\n");
        return 1;
    }

    if (a >= b) {
        printf("Ошибка: a должен быть меньше b.\n");
        return 1;
    }

    // Протабулирование функции f(x) = ctg^2(ln x) = (cos(ln x)/sin(ln x))^2
    printf("x f(x)\n");
    x = a;

    while (x <= b) {
        // Проверка на область определения: ln(x) должен быть определён
        // ln(x) определён только при x > 0
        if (x <= 0) {
            printf("Ошибка: x должно быть больше 0.\n");
            break;
        }

        double ln_x = log(x);
        double cos_ln_x = cos(ln_x);
        double sin_ln_x = sin(ln_x);

        // Проверка на sin(ln(x)) == 0 (тогда ctg не определён)
        if (fabs(sin_ln_x) < 1e-15) {
            printf("Ошибка: f(x) не определено при x = %.6f (sin(ln(x)) = 0).\n", x);
            x += h;
            continue;
        }

        double f_x = (cos_ln_x / sin_ln_x) * (cos_ln_x / sin_ln_x);
        printf("%.2f %.6f\n", x, f_x);

        x += h;
    }

    return 0;
}

