#include <math.h>

int main() {
    double a, b, c, d, k;

    // Считываем коэффициенты
    printf("Введите коэффициенты a, b, c, d, k: ");
    scanf("%lf %lf %lf %lf %lf", &a, &b, &c, &d, &k);

    // Уравнение: a*x^2 + (b - d)*x + (c - k) = 0
    double A = a;
    double B = b - d;
    double C = c - k;

    // Вычисляем дискриминант
    double D = B * B - 4 * A * C;

    // Решение уравнения
    if (D < 0) {
        printf("no roots\n");
    } else if (D == 0) {
        double x = -B / (2 * A);
        printf("%.6f\n", x);
    } else {
        double sqrtD = sqrt(D);
        double x1 = (-B - sqrtD) / (2 * A);
        double x2 = (-B + sqrtD) / (2 * A);

        // Выводим корни в порядке возрастания
        if (x1 > x2) {
            printf("%.6f %.6f\n", x2, x1);
        } else {
            printf("%.6f %.6f\n", x1, x2);
        }
    }

    return 0;
}

