#include <stdio.h>

int main() {
    int n;
    printf("Введите размер матрицы n: ");
    scanf("%d", &n);

    // Создаем матрицу n x n
    int matrix[n][n];

    int num = 1;  // Начальное значение для заполнения

    // Заполняем матрицу по диагоналям
    for (int d = 0; d < 2 * n - 1; d++) {
        int row_start = (d < n) ? 0 : d - n + 1;
        int col_start = (d < n) ? d : 0;
        int row_end = (d < n) ? d : n - 1;
        int col_end = (d < n) ? 0 : d - n + 1;

        // Определяем направление: сверху вниз (нечетные d) или снизу вверх (четные d)
        int direction = (d % 2 == 0) ? 1 : -1;

        // Заполняем диагональ
        if (d % 2 == 0) {
            // Сверху вниз
            for (int i = row_start, j = col_start; i <= row_end && j >= col_start; i++, j--) {
                matrix[i][j] = num++;
            }
        } else {
            // Снизу вверх
            for (int i = row_end, j = col_start; i >= row_start && j <= col_end; i--, j++) {
                matrix[i][j] = num++;
            }
        }
    }

    // Выводим матрицу
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            printf("%4d", matrix[i][j]);
        }
        printf("\n");
    }

    return 0;
}

