int main() {
    int n;
    printf("Введите размер матрицы n: ");
    scanf("%d", &n);

    // Проверка корректности ввода
    if (n <= 0) {
        printf("Размер матрицы должен быть положительным.\n");
        return 1;
    }

    // Создание матрицы
    int matrix[n][n];

    printf("Введите элементы матрицы:\n");
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &matrix[i][j]);
        }
    }

    // Находим элемент с наибольшим по модулю значением
    int max_abs_value = 0;
    int max_row = 0, max_col = 0;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (abs(matrix[i][j]) > abs(max_abs_value)) {
                max_abs_value = matrix[i][j];
                max_row = i;
                max_col = j;
            }
        }
    }

    // Проверяем, что найден хотя бы один элемент (должен быть)
    if (max_abs_value == 0) {
        printf("Все элементы равны нулю.\n");
        // Выводим матрицу без изменений
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                printf("%d ", matrix[i][j]);
            }
            printf("\n");
        }
        return 0;
    }

    // Создаем копию матрицы для результата
    int result[n][n];

    // Копируем матрицу
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            result[i][j] = matrix[i][j];
        }
    }

    // Поменять строку с наибольшим элементом с последней строкой
    for (int j = 0; j < n; j++) {
        int temp = result[max_row][j];
        result[max_row][j] = result[n-1][j];
        result[n-1][j] = temp;
    }

    // Поменять столбец с наибольшим элементом с последним столбцом
    for (int i = 0; i < n; i++) {
        int temp = result[i][max_col];
        result[i][max_col] = result[i][n-1];
        result[i][n-1] = temp;
    }

    // Выводим полученную матрицу
    printf("\nПолученная матрица:\n");
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            printf("%d ", result[i][j]);
        }
        printf("\n");
    }

    return 0;
}

