    for (i = 0; i < 7; i++) {
        for (j = 0; j < 7; j++) {
            scanf("%d", &matrix[i][j]);
        }
    }

    // Для каждого столбца упорядочиваем элементы между максимальным и минимальным
    for (j = 0; j < 7; j++) {
        // Находим минимальный и максимальный элементы в столбце
        int min_val = matrix[0][j];
        int max_val = matrix[0][j];
        int min_idx = 0;
        int max_idx = 0;

        for (i = 1; i < 7; i++) {
            if (matrix[i][j] < min_val) {
                min_val = matrix[i][j];
                min_idx = i;
            }
            if (matrix[i][j] > max_val) {
                max_val = matrix[i][j];
                max_idx = i;
            }
        }

        // Собираем элементы между min и max (не включая крайние)
        int elements[50]; // Максимально 50 элементов, но в 7x7 — максимум 5 элементов между
        int count = 0;

        for (i = 0; i < 7; i++) {
            if (i != min_idx && i != max_idx && (matrix[i][j] >= min_val && matrix[i][j] <= max_val)) {
                elements[count++] = matrix[i][j];
            }
        }

        // Сортируем элементы по возрастанию
        for (int k = 0; k < count - 1; k++) {
            for (int l = 0; l < count - k - 1; l++) {
                if (elements[l] > elements[l + 1]) {
                    int temp = elements[l];
                    elements[l] = elements[l + 1];
                    elements[l + 1] = temp;
                }
            }
        }

        // Возвращаем элементы в столбце, заменяя только те, что между min и max
        int idx = 0;
        for (i = 0; i < 7; i++) {
            if (i == min_idx || i == max_idx) {
                // Крайние элементы не трогаем
                continue;
            }
            if (matrix[i][j] >= min_val && matrix[i][j] <= max_val) {
                matrix[i][j] = elements[idx++];
            }
        }
    }

    // Выводим полученную матрицу
    printf("\nМатрица после упорядочивания столбцов:\n");
    for (i = 0; i < 7; i++) {
        for (j = 0; j < 7; j++) {
            printf("%d ", matrix[i][j]);
        }
        printf("\n");
    }

    return 0;
}

