int main() {
    double x, y, y_next;

    printf("Введите вещественное число x: ");
    scanf("%lf", &x);

    // Для x = 0 выводим 0
    if (x == 0.0) {
        printf("0.000000\n");
        return 0;
    }

    // Начальное приближение y(0) = x
    y = x;

    // Итерационная формула: y(i+1) = 0.5 * (y(i) + 3*x / (2*y(i)^2 + x/y(i)))
    // Прекращаем, когда |y(i+1) - y(i)| < 1e-5
    double epsilon = 1e-5;

    do {
        y_next = 0.5 * (y + 3.0 * x / (2.0 * y * y + x / y));
        if (fabs(y_next - y) < epsilon) {
            break;
        }
        y = y_next;
    } while (1);

    printf("%.6f\n";

    return 0;
}

