int main() {
    int op;
    scanf("%d", &op);

    if (op == 1) {
        int h, m, s, delta;
        scanf("%d %d %d %d", &h, &m, &s, &delta);

        // Общее количество секунд в начальном времени
        int total_seconds = h * 3600 + m * 60 + s;

        // Вычитаем delta секунд, с учётом переноса через полночь
        total_seconds = (total_seconds - delta + 86400) % 86400;

        // Преобразуем обратно в h, m, s
        int new_h = total_seconds / 3600;
        int remaining = total_seconds % 3600;
        int new_m = remaining / 60;
        int new_s = remaining % 60;

        printf("%d %d %d\n", new_h, new_m, new_s);
    } else if (op == 2) {
        int h1, m1, s1, h2, m2, s2;
        scanf("%d %d %d %d %d %d", &h1, &m1, &s1, &h2, &m2, &s2);

        // Преобразуем оба времени в секунды с начала суток
        int sec1 = h1 * 3600 + m1 * 60 + s1;
        int sec2 = h2 * 3600 + m2 * 60 + s2;

        // Находим абсолютную разность
        int diff = (sec1 > sec2) ? (sec1 - sec2) : (sec2 - sec1);

        printf("%d\n", diff);
    }

    return 0;
}

