    int min_row = -1, min_col = -1;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i > j && matrix[i][j] < min_val) {
                min_val = matrix[i][j];
                min_row = i;
                min_col = j;
            }
        }
    }

    // Находим максимальный элемент среди элементов выше побочной диагонали (i + j < n - 1)
    int max_val = -999999;
