int main() {
    int n;
    printf("Введите количество элементов: ");
    scanf("%d", &n);

    if (n <= 0) {
        printf("Количество элементов должно быть положительным.\n");
        return 1;
    }

    int arr[n];
    printf("Введите %d целых чисел:\n", n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    // (1) Номер минимального элемента (нумерация с 1)
    int min_idx = 0;
    for (int i = 1; i < n; i++) {
        if (arr[i] < arr[min_idx]) {
            min_idx = i;
        }
    }
    printf("Номер минимального элемента: %d\n", min_idx + 1);

    // (2) Произведение элементов между первым и вторым отрицательными элементами
    int first_neg = -1, second_neg = -1;
    for (int i = 0; i < n; i++) {
        if (arr[i] < 0) {
            if (first_neg == -1) {
                first_neg = i;
            } else if (second_neg == -1) {
                second_neg = i;
                break;
            }
        }
    }

    if (second_neg == -1) {
        printf("Произведение элементов между первым и вторым отрицательными элементами: 0\n");
    } else {
        long long product = 1;
        for (int i = first_neg + 1; i < second_neg; i++) {
            product *= arr[i];
        }
        printf("Произведение элементов между первым и вторым отрицательными элементами: %lld\n", product);
    }

    // (3) Преобразованный массив: сначала элементы, модуль которых не превышает 1, затем остальные
    int transformed[n];
    int idx1 = 0, idx2 = 0;

    // Сначала элементы с |x| <= 1
    for (int i = 0; i < n; i++) {
        if (abs(arr[i]) <= 1) {
            transformed[idx1++] = arr[i];
        }
    }

    // Затем остальные элементы
    for (int i = 0; i < n; i++) {
        if (abs(arr[i]) > 1) {
            transformed[idx1 + idx2++] = arr[i];
        }
    }

    // Вывод преобразованного массива
    printf("Преобразованный массив: ");
    for (int i = 0; i < idx1; i++) {
        printf("%d ", transformed[i]);
    }
    for (int i = 0; i < idx2; i++) {
        printf("%d ", transformed[idx1 + i]);
    }
    printf("\n");

    return 0;
}

