#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// Функция вычисления характеристики столбца (сумма модулей отрицательных нечётных элементов)
int getCharacteristic(int matrix[][100], int n, int m, int col) {
    int sum = 0;
    for (int i = 0; i < n; i++) {
        int element = matrix[i][col];
        // Проверяем, является ли элемент отрицательным и нечётным
        if (element < 0 && element % 2 != 0) {
            sum += abs(element);
        }
    }
    return sum;
}

// Функция обмена двух столбцов в матрице
void swapColumns(int matrix[][100], int n, int m, int col1, int col2) {
    for (int i = 0; i < n; i++) {
        int temp = matrix[i][col1];
        matrix[i][col1] = matrix[i][col2];
        matrix[i][col2] = temp;
    }
}

// Функция сортировки столбцов по возрастанию характеристик
void sortColumns(int matrix[][100], int n, int m) {
    for (int i = 0; i < m - 1; i++) {
        for (int j = 0; j < m - i - 1; j++) {
            int char1 = getCharacteristic(matrix, n, m, j);
            int char2 = getCharacteristic(matrix, n, m, j + 1);
            if (char1 > char2) {
                swapColumns(matrix, n, m, j, j + 1);
            }
        }
    }
}

