#include <stdio.h>

// Сортировка выбором
void selectionSort(int arr[], int n, int *comparisons) {
    *comparisons = 0;
    for (int i = 0; i < n - 1; i++) {
        int min_idx = i;
        for (int j = i + 1; j < n; j++) {
            (*comparisons)++;
            if (arr[j] < arr[min_idx]) {
                min_idx = j;
            }
        }
        if (min_idx != i) {
            int temp = arr[i];
            arr[i] = arr[min_idx];
            arr[min_idx] = temp;
        }
    }
}

// Шейкер-сортировка (bidirectional bubble sort)
void shakeSort(int arr[], int n, int *comparisons) {
    *comparisons = 0;
    int left = 0, right = n - 1;
    int swapped;

    do {
        swapped = 0;
        // Сортировка слева направо
        for (int i = left; i < right; i++) {
            (*comparisons)++;
            if (arr[i] > arr[i + 1]) {
                int temp = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = temp;
                swapped = 1;
            }
        }
        if (!swapped) break;
        right--;

        // Сортировка справа налево
        for (int i = right; i > left; i--) {
            (*comparisons)++;
            if (arr[i] < arr[i - 1]) {
                int temp = arr[i];
                arr[i] = arr[i - 1];
                arr[i - 1] = temp;
                swapped = 1;
            }
        }
        left++;
    } while (swapped);
}

