#include <stdio.h>

// Функция для вычисления определителя матрицы n x n с помощью разложения по первому столбцу
// Используется рекурсивный алгоритм (разложение по строке/столбцу)
long long determinant(int n, int matrix[100][100]) {
    long long det = 0;

    // Базовый случай: 1x1 матрица
    if (n == 1) {
        return matrix[0][0];
    }

    // Базовый случай: 2x2 матрица
    if (n == 2) {
        return (long long)matrix[0][0] * matrix[1][1] - (long long)matrix[0][1] * matrix[1][0];
    }

    // Рекурсивный случай: разложение по первому столбцу
    for (int i = 0; i < n; i++) {
        // Создаём подматрицу размером (n-1) x (n-1)
        int sub_matrix[99][99];
        int sub_size = n - 1;

        // Копируем элементы подматрицы
        int idx = 0;
        for (int row = 0; row < n; row++) {
            if (row == i) continue;
            for (int col = 0; col < n; col++) {
                if (col == 0) {
                    sub_matrix[idx][0] = matrix[row][col];
                } else {
                    sub_matrix[idx][col - 1] = matrix[row][col];
                }
            }
            idx++;
        }

        // Вычисляем определитель подматрицы
        long long minor_det = determinant(sub_size, sub_matrix);

        // Слагаем с учётом знака: (-1)^(i+1)
        if (i % 2 == 0) {
            det += (long long)matrix[i][0] * minor_det;
        } else {
            det -= (long long)matrix[i][0] * minor_det;
        }
    }

    return det;
}

