    scanf("%d", &N);

    // Если N меньше 2, то простых чисел нет
    if (N < 2) {
        printf("\n");
        return 0;
    }

    // Создаем булевый массив для хранения простоты чисел
    // is_prime[i] будет true, если i — простое число
    int is_prime[N + 1];
    for (int i = 0; i <= N; i++) {
        is_prime[i] = 1;
    }

    // 0 и 1 не являются простыми числами
    is_prime[0] = is_prime[1] = 0;

    // Алгоритм решета Эратосфена
    for (int i = 2; i * i <= N; i++) {
        if (is_prime[i]) {
            // Отмечаем все кратные i как не простые
            for (int j = i * i; j <= N; j += i) {
                is_prime[j] = 0;
            }
        }
    }

    // Собираем простые числа
    int primes[10000]; // Массив для хранения простых чисел
    int count = 0;

    for (int i = 2; i <= N; i++) {
        if (is_prime[i]) {
            primes[count++] = i;
        }
    }

    // Выводим простые числа через пробел
    if (count == 0) {
        printf("\n");
    } else {
        for (int i = 0; i < count; i++) {
            printf("%d", primes[i]);
            if (i < count - 1) {
                printf(" ");
            }
        }
        printf("\n");
    }

    return 0;
}
